//! S04 reading-order battery: the independent `reader_reading_order` surface
//! over the pinned mixed WordML fixture.
//!
//! The per-view token lists below are a **handwritten XML oracle** derived from
//! `fixtures/reader/mixed-wordml.xml` (never generated by the code under test).
//! The fixture is pinned by sha256. The independent index must re-derive the
//! same order from the substrate event walk, must refuse a tampered projection
//! with a typed error, and must prove that reading order is not the `tN` record
//! order, not a `source_pos` sort and not a `semantic` sort.
//!
//! Non-claims: `[bounded]` to the one pinned fixture; no raw decoded legal text
//! is logged; no R1000 closure.

use ln_decode::reader_contract::ReaderViewKind;
use ln_decode::reader_projection::{
    ProjectedSegment, ReaderProjection, SegmentOrigin, ViewId, build_projection,
};
use ln_decode::reader_reading_order::{ReadingOrderErrorKind, ReadingOrderIndex};
use ln_decode::source_package::{Limits, Record, capture};

const XML: &str = include_str!("fixtures/reader/mixed-wordml.xml");
const FIXTURE_SHA256: &str = "d2fc1cd17f0697f575e94f09d83da5027d73afd37c700772eafa4c4a4fbc76db";

fn fixture() -> (Vec<Record>, ReaderProjection) {
    let package = capture(XML.as_bytes(), &Limits::default()).expect("fixture must capture");
    assert_eq!(
        package.manifest().source.sha256,
        FIXTURE_SHA256,
        "fixture content changed; re-pin FIXTURE_SHA256 and the handwritten oracle"
    );
    let records = package.records().to_vec();
    let projection = build_projection(&records).expect("projection must build");
    (records, projection)
}

fn view_id(projection: &ReaderProjection, kind: ReaderViewKind, element_ref: &str) -> ViewId {
    projection
        .views
        .iter()
        .find(|view| view.kind == kind && view.element_ref.as_str() == element_ref)
        .unwrap_or_else(|| panic!("view {kind:?} {element_ref} missing"))
        .id
        .clone()
}

fn segment<'a>(projection: &'a ReaderProjection, id: &str) -> &'a ProjectedSegment {
    projection
        .segments
        .iter()
        .find(|segment| segment.id.as_str() == id)
        .unwrap_or_else(|| panic!("segment {id} missing"))
}

/// `tN` for a source segment, `derived:<kind>` for a rendered control.
fn token(segment: &ProjectedSegment) -> String {
    match segment.origin {
        SegmentOrigin::SourceFragment => segment
            .fragment_ref
            .as_ref()
            .expect("source segment carries a fragment")
            .as_str()
            .to_string(),
        SegmentOrigin::Derived(kind) => format!("derived:{}", kind.as_str()),
    }
}

fn reading_tokens(
    index: &ReadingOrderIndex,
    projection: &ReaderProjection,
    view: &ViewId,
) -> Vec<String> {
    index
        .reading_order(view)
        .expect("primary view is readable")
        .iter()
        .map(|id| token(segment(projection, id.as_str())))
        .collect()
}

fn strings(values: &[&str]) -> Vec<String> {
    values.iter().map(|value| value.to_string()).collect()
}

#[test]
fn reading_order_matches_handwritten_oracle() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("untampered index builds");

    let oracle: &[(ReaderViewKind, &str, &[&str], &str)] = &[
        (ReaderViewKind::Paragraph, "e2", &["t0"], "Alpha"),
        (
            ReaderViewKind::Paragraph,
            "e5",
            &["t1", "derived:tab", "t2"],
            "Beta\tPAGE",
        ),
        (ReaderViewKind::Paragraph, "e13", &["t3"], "Gamma"),
        (ReaderViewKind::Residual, "e13", &["t4"], " "),
        (ReaderViewKind::Residual, "e16", &["t5"], "Delta"),
        (
            ReaderViewKind::Paragraph,
            "e19",
            &["derived:line_break", "derived:page_break", "t6"],
            "\n\nEpsilon",
        ),
        (ReaderViewKind::Paragraph, "e24", &["t7", "t8"], "ZetaEta"),
        (
            ReaderViewKind::Paragraph,
            "e29",
            &["t9", "t10"],
            "ThetaIota",
        ),
        (ReaderViewKind::Paragraph, "e38", &["t13"], "NBSP:\u{a0}Mu"),
        (ReaderViewKind::Paragraph, "e43", &["t14"], "Nu"),
        (
            ReaderViewKind::Residual,
            "e0",
            &["t11", "t12"],
            "KappaLambda",
        ),
    ];
    for (kind, element_ref, expected_tokens, expected_output) in oracle {
        let view = view_id(&projection, *kind, element_ref);
        assert_eq!(
            reading_tokens(&index, &projection, &view),
            strings(expected_tokens),
            "reading tokens for {kind:?} {element_ref}"
        );
        assert_eq!(
            index.view_output(&view).expect("primary view renders"),
            *expected_output,
            "view output for {kind:?} {element_ref}"
        );
        // The independent order must reproduce the projection's declared order.
        let declared = projection
            .view(&view)
            .expect("view exists")
            .segment_refs
            .iter()
            .map(|id| id.as_str().to_string())
            .collect::<Vec<_>>();
        let derived = index
            .reading_order(&view)
            .expect("primary view is readable")
            .iter()
            .map(|id| id.as_str().to_string())
            .collect::<Vec<_>>();
        assert_eq!(
            derived, declared,
            "declared order for {kind:?} {element_ref}"
        );
    }

    // An empty primary view reads as an empty string.
    let empty = view_id(&projection, ReaderViewKind::Residual, "e46");
    assert!(index.reading_order(&empty).expect("readable").is_empty());
    assert_eq!(index.view_output(&empty).expect("renders"), "");
}

#[test]
fn reading_order_is_not_source_pos_or_semantic_order() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");

    // (a) Tail where capture owner != semantic owner: `t4` is the tail of
    // paragraph `e13`, but belongs to the residual `e13` reading view, and its
    // semantic is whitespace. Reading order is `t3` (paragraph) then `t4`
    // (residual); a `source_pos` sort puts `t4` (element `e13`, pos 13) before
    // `t3` (element `e15`, pos 15).
    let tail = segment(&projection, "s7");
    assert_eq!(tail.fragment_ref.as_ref().unwrap().as_str(), "t4");
    assert_eq!(tail.element_ref.as_str(), "e13");
    assert_eq!(tail.semantic.as_str(), "whitespace");
    let paragraph_e13 = view_id(&projection, ReaderViewKind::Paragraph, "e13");
    let residual_e13 = view_id(&projection, ReaderViewKind::Residual, "e13");
    assert_ne!(paragraph_e13, residual_e13);
    assert_eq!(tail.view, residual_e13);

    let reading_pair = ["s6".to_string(), "s7".to_string()];
    let mut source_pos_pair = reading_pair.clone();
    source_pos_pair.sort_by_key(|id| segment(&projection, id).source_pos);
    assert_eq!(source_pos_pair, ["s7".to_string(), "s6".to_string()]);
    assert_ne!(
        reading_pair, source_pos_pair,
        "reading order must not be a source_pos sort"
    );

    // (b) Shared-fragment semantic order: paragraph `e24` reads `t7`
    // (field_code) then `t8` (body); a `semantic` sort puts `t8` (`body`) before
    // `t7` (`field_code`).
    let e24 = view_id(&projection, ReaderViewKind::Paragraph, "e24");
    let reading = index.reading_order(&e24).expect("readable").to_vec();
    let mut semantic = reading.clone();
    semantic.sort_by(|left, right| {
        segment(&projection, left.as_str())
            .semantic
            .as_str()
            .cmp(segment(&projection, right.as_str()).semantic.as_str())
    });
    assert_eq!(
        reading,
        vec![
            ln_decode::reader_projection::SegmentId::from("s12"),
            ln_decode::reader_projection::SegmentId::from("s13"),
        ]
    );
    assert_eq!(
        semantic,
        vec![
            ln_decode::reader_projection::SegmentId::from("s13"),
            ln_decode::reader_projection::SegmentId::from("s12"),
        ]
    );
    assert_ne!(
        reading, semantic,
        "reading order must not be a semantic sort"
    );
}

#[test]
fn record_order_differs_from_reading_order() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");

    // The substrate lays the `tN` records out as t0..t14.
    let record: Vec<String> = index
        .record_order(&records)
        .iter()
        .map(|fragment| fragment.as_str().to_string())
        .collect();
    let expected: Vec<String> = (0..15).map(|n| format!("t{n}")).collect();
    assert_eq!(record, expected, "record order is the raw tN stream");

    // Flattened reading order is anchored at residual `e0` first, so it differs.
    assert!(
        !index.is_record_order_coincident(&records),
        "reading order must not coincide with record order"
    );
}

#[test]
fn ordinal_gap_is_refused() {
    let (records, mut projection) = fixture();
    let target = projection
        .segments
        .iter_mut()
        .find(|segment| segment.id.as_str() == "s3")
        .expect("s3 exists");
    target.ordinal = 99;
    projection.reseal();

    let errors = ReadingOrderIndex::build(&projection, &records).expect_err("must refuse");
    assert!(
        errors
            .iter()
            .any(|error| error.kind() == ReadingOrderErrorKind::OrdinalGap),
        "expected OrdinalGap, got {errors:?}"
    );
}

#[test]
fn output_gap_is_refused() {
    let (records, mut projection) = fixture();
    let target = projection
        .segments
        .iter_mut()
        .find(|segment| segment.id.as_str() == "s4")
        .expect("s4 exists");
    target.output_start = 50;
    projection.reseal();

    let errors = ReadingOrderIndex::build(&projection, &records).expect_err("must refuse");
    assert!(
        errors
            .iter()
            .any(|error| error.kind() == ReadingOrderErrorKind::OutputGap),
        "expected OutputGap, got {errors:?}"
    );
}

#[test]
fn unknown_segment_ref_is_refused() {
    let (records, mut projection) = fixture();
    projection
        .segments
        .retain(|segment| segment.id.as_str() != "s4");
    projection.reseal();

    let errors = ReadingOrderIndex::build(&projection, &records).expect_err("must refuse");
    assert!(
        errors
            .iter()
            .any(|error| error.kind() == ReadingOrderErrorKind::UnknownSegment),
        "expected UnknownSegment, got {errors:?}"
    );
}

#[test]
fn resealed_permutation_is_order_mismatch() {
    let (records, mut projection) = fixture();
    let e5 = view_id(&projection, ReaderViewKind::Paragraph, "e5");
    let view = projection
        .views
        .iter_mut()
        .find(|view| view.id == e5)
        .expect("view exists");
    // [s3 (t1), s4 (tab), s5 (t2)] -> [s4 (tab), s3 (t1), s5 (t2)].
    view.segment_refs = vec![
        ln_decode::reader_projection::SegmentId::from("s4"),
        ln_decode::reader_projection::SegmentId::from("s3"),
        ln_decode::reader_projection::SegmentId::from("s5"),
    ];
    projection.reseal();

    // The independent re-derivation must catch the permutation without trusting
    // the freshly recomputed seal.
    let errors = ReadingOrderIndex::build(&projection, &records).expect_err("must refuse");
    assert!(
        errors
            .iter()
            .any(|error| error.kind() == ReadingOrderErrorKind::OrderMismatch),
        "expected OrderMismatch, got {errors:?}"
    );
}

#[test]
fn non_primary_view_is_refused() {
    let (records, projection) = fixture();
    let index = ReadingOrderIndex::build(&projection, &records).expect("index builds");

    // Table / row / cell / note are navigation views, not reading-order views.
    for (kind, element_ref) in [
        (ReaderViewKind::Table, "e10"),
        (ReaderViewKind::Row, "e11"),
        (ReaderViewKind::Cell, "e12"),
        (ReaderViewKind::Note, "e42"),
    ] {
        let view = view_id(&projection, kind, element_ref);
        let error = index
            .reading_order(&view)
            .expect_err("navigation view must be refused");
        assert_eq!(error.kind(), ReadingOrderErrorKind::NotPrimaryView);
        let error = index
            .view_output(&view)
            .expect_err("navigation view must be refused");
        assert_eq!(error.kind(), ReadingOrderErrorKind::NotPrimaryView);
    }
}
